const tabs = [...document.querySelectorAll('.aba')];
function show(id) {
  tabs.forEach(t => {
    const sel = t.id === id;
    t.setAttribute('aria-selected', sel);
    document.getElementById(t.getAttribute('aria-controls')).hidden = !sel;
    if (sel) t.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' }); // no celular, a aba escolhida desliza para o meio da faixa
  });
  const tok = id.slice(2);
  if (location.hash.slice(1) !== tok) history.replaceState(null, '', '#' + tok);
}
tabs.forEach(t => t.addEventListener('click', () => show(t.id)));
document.querySelectorAll('[data-ir]').forEach(b => b.addEventListener('click', () => { show(b.dataset.ir); window.scrollTo({ top: 0 }); }));
const inicial = tabs.find(t => t.id === 't-' + location.hash.slice(1));
if (inicial) show(inicial.id);

/* ===== gráficos ===== */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const svg = (w, h, rotulo, corpo) => `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${rotulo}">${corpo}</svg>`;
const fmt1 = n => n.toFixed(1).replace('.', ',');
function figura(titulo, nota, corpo, extra) {
  const f = document.createElement('figure');
  f.className = 'fig' + (extra ? ' ' + extra : '');
  f.innerHTML = `<div class="figt"><h3>${titulo}</h3><span>${nota}</span></div>${corpo}`;
  $$('[data-atraso]', f).forEach(e => { e.style.animationDelay = e.dataset.atraso + 'ms'; });
  return f;
}

/* barras horizontais: anos por tecnologia */
function barras(dados, max, unidade) {
  const W = 520, esq = 112, dir = 56, topo = 6, lin = 38, h = topo + dados.length * lin + 28;
  const x = v => esq + (W - esq - dir) * v / max;
  let s = '';
  for (let i = 0; i <= max; i++) s += `<line class="grade" x1="${x(i)}" x2="${x(i)}" y1="${topo}" y2="${h - 24}"/><text class="mono" x="${x(i)}" y="${h - 8}" text-anchor="middle">${i}</text>`;
  dados.forEach((d, i) => {
    const y = topo + i * lin + 5;
    s += `<text class="tx" x="0" y="${y + 16}">${d.n}</text>` +
      `<rect class="b-${d.c} cresce" x="${esq}" y="${y}" width="${x(d.v) - esq}" height="24" rx="5" data-atraso="${i * 90}"><title>${d.n}: ${d.v} ${unidade}</title></rect>` +
      `<text class="mono tx" x="${x(d.v) + 8}" y="${y + 16}">${d.v} ${unidade}</text>`;
  });
  return svg(W, h, 'Gráfico de barras: ' + dados.map(d => `${d.n} ${d.v} ${unidade}`).join(', '), s);
}

/* linha do tempo da carreira */
const agora = new Date();
const hoje = agora.getFullYear() + (agora.getMonth() + agora.getDate() / 31) / 12;
const mesesDotnet = (agora.getFullYear() - 2025) * 12 + (agora.getMonth() - 1);
function cronologia() {
  const W = 580, esq = 152, dir = 18, topo = 26, lin = 46, a0 = 2019, a1 = Math.max(2027, Math.ceil(hoje));
  const itens = [
    { n: 'UniCesumar', s: 'Tecnólogo em ADS', a: 2019, b: 2022, c: 'n', t: '2019 – 2021' },
    { n: 'Mecânica Avançada', s: 'Suporte técnico', a: 2021.33, b: 2023.08, c: 't', t: 'mai/2021 – fev/2023' },
    { n: 'C4 Sistemas', s: 'Desenvolvedor Java', a: 2023.08, b: 2025.08, c: 'v', t: 'fev/2023 – jan/2025' },
    { n: 'Moderna / Benner', s: 'Desenvolvedor .NET', a: 2025.08, b: hoje, c: 'a', t: 'fev/2025 – atual' },
  ];
  const x = v => esq + (W - esq - dir) * (v - a0) / (a1 - a0);
  const h = topo + itens.length * lin + 28;
  let s = '';
  for (let y = a0; y <= a1; y++) s += `<line class="grade" x1="${x(y)}" x2="${x(y)}" y1="${topo - 6}" y2="${h - 24}"/><text class="mono" x="${x(y)}" y="${h - 8}" text-anchor="middle">${y}</text>`;
  itens.forEach((d, i) => {
    const y = topo + i * lin;
    s += `<text class="tx" x="0" y="${y + 15}">${d.n}</text><text class="mono peq" x="0" y="${y + 31}">${d.s}</text>` +
      `<rect class="b-${d.c} cresce" x="${x(d.a)}" y="${y + 4}" width="${x(d.b) - x(d.a)}" height="26" rx="5" data-atraso="${i * 110}"><title>${d.n} · ${d.t}</title></rect>`;
  });
  s += `<line class="hoje" x1="${x(hoje)}" x2="${x(hoje)}" y1="${topo - 10}" y2="${h - 24}"/><text class="mono hoje-t" x="${x(hoje) - 5}" y="${topo - 12}" text-anchor="end">hoje</text>`;
  return svg(W, h, 'Linha do tempo: ' + itens.map(d => `${d.n}, ${d.s}, ${d.t}`).join('; '), s);
}

/* rosca: meses por fase */
function rosca() {
  const fases = [{ n: 'Suporte técnico', m: 21, c: 't' }, { n: 'Java', m: 24, c: 'v' }, { n: '.NET', m: mesesDotnet, c: 'a' }];
  const total = fases.reduce((t, f) => t + f.m, 0);
  const cx = 88, cy = 88, r = 58, C = 2 * Math.PI * r;
  let acc = 0, s = '';
  fases.forEach(f => {
    const len = C * f.m / total;
    s += `<circle class="fatia s-${f.c}" cx="${cx}" cy="${cy}" r="${r}" stroke-dasharray="${Math.max(len - 2, 0)} ${C - Math.max(len - 2, 0)}" stroke-dashoffset="${-acc}" transform="rotate(-90 ${cx} ${cy})"><title>${f.n}: ${f.m} meses</title></circle>`;
    acc += len;
  });
  s += `<text class="grande" x="${cx}" y="${cy + 4}" text-anchor="middle">${fmt1(total / 12)}</text><text class="mono" x="${cx}" y="${cy + 22}" text-anchor="middle">anos</text>`;
  fases.forEach((f, i) => {
    const y = 40 + i * 38;
    s += `<rect class="b-${f.c}" x="196" y="${y - 11}" width="12" height="12" rx="3"/><text class="tx" x="218" y="${y}">${f.n}</text><text class="mono" x="218" y="${y + 16}">${f.m} meses · ${Math.round(100 * f.m / total)}%</text>`;
  });
  return svg(420, 176, 'Gráfico de rosca do tempo de carreira: ' + fases.map(f => `${f.n} ${f.m} meses`).join(', '), s);
}

/* navegação do Konta: 6 telas e rotas */
function navegacaoKonta() {
  const ic = {
    dash: '<rect x="0" y="0" width="7" height="7" rx="1.5"/><rect x="10" y="0" width="7" height="7" rx="1.5"/><rect x="0" y="10" width="7" height="7" rx="1.5"/><rect x="10" y="10" width="7" height="7" rx="1.5"/>',
    lanc: '<path d="M0 3h17M0 9h17M0 15h11"/>',
    cal: '<rect x="0" y="2" width="17" height="15" rx="2"/><path d="M0 7h17M5 0v4M12 0v4"/>',
    hist: '<path d="M2 17V9M8.5 17V2M15 17V6"/>',
    res: '<circle cx="8.5" cy="8.5" r="8"/><path d="M8.5 4v9M5.8 6.6c0-1.3 1.3-1.9 2.7-1.9s2.7.6 2.7 1.9-1.2 1.7-2.7 1.9-2.7.6-2.7 1.9 1.2 1.9 2.7 1.9 2.7-.6 2.7-1.9"/>',
    cfg: '<path d="M0 4h17M0 13h17"/><circle cx="11" cy="4" r="2.5"/><circle cx="5" cy="13" r="2.5"/>',
  };
  const telas = [['dash', 'Dashboard', '/'], ['lanc', 'Lançamentos', '/transactions'], ['cal', 'Calendário', '/calendar'], ['hist', 'Histórico', '/history'], ['res', 'Reservas', '/reservas'], ['cfg', 'Configurações', '/settings']];
  let s = '';
  telas.forEach((t, i) => {
    const x = (i % 3) * 180, y = Math.floor(i / 3) * 76;
    s += `<rect class="caixa" x="${x}" y="${y}" width="160" height="60" rx="8"/><g class="ico" transform="translate(${x + 14} ${y + 21})">${ic[t[0]]}</g>` +
      `<text class="tx" x="${x + 44}" y="${y + 27}">${t[1]}</text><text class="mono" x="${x + 44}" y="${y + 45}">${t[2]}</text>`;
  });
  return svg(520, 136, 'Seis telas do Konta e suas rotas: ' + telas.map(t => `${t[1]} ${t[2]}`).join(', '), s);
}

/* arquitetura do rpg-mesa: referências reais entre projetos */
function arquiteturaMesa() {
  const cx = (x, y, w, h, nome, dest) => `<rect class="caixa${dest ? ' dest' : ''}" x="${x}" y="${y}" width="${w}" height="${h}" rx="7"/><text class="mono tx" x="${x + w / 2}" y="${y + h / 2 + 4}" text-anchor="middle">${nome}</text>`;
  const seta = d => `<path class="lig" d="${d}" marker-end="url(#ponta)"/>`;
  const s = `<defs><marker id="ponta" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="8" markerHeight="8" orient="auto"><path class="pt" d="M0 0L8 4L0 8z"/></marker></defs>` +
    cx(10, 10, 170, 36, 'PainelDed.Api.Testes') + cx(10, 96, 170, 36, 'PainelDed.Api') + cx(200, 96, 140, 36, 'PainelDed.Ingestor') +
    cx(190, 184, 160, 40, 'PainelDed.Nucleo', true) + cx(380, 184, 150, 40, 'PainelDed.Nucleo.Testes') +
    seta('M95 46V92') + seta('M95 132V158H230V180') + seta('M270 132V180') + seta('M380 204H354') +
    `<text class="peq" x="0" y="242">seta: referência de projeto (quem aponta depende de quem recebe)</text>`;
  return svg(540, 250, 'Referências entre projetos: Api e Ingestor dependem do Nucleo; Api.Testes depende da Api; Nucleo.Testes depende do Nucleo', s);
}

